/* Logo intro: once per tab, dismissible immediately, independent of the book runtime. */
(()=>{'use strict';const root=document.documentElement,key='nexa360-intro-seen-v1';const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let seen=false;try{seen=sessionStorage.getItem(key)==='1';}catch{}
const shouldShow=!seen&&!location.hash;let active=false,overlay,skip,content=[],previousFocus=null,started=0,autoTimer=null,exitTimer=null,failsafe=null,ready=false;
function clearTimers(){clearTimeout(autoTimer);clearTimeout(exitTimer);clearTimeout(failsafe);}
function cleanup(restoreFocus=true){clearTimers();root.classList.remove('intro-pending','intro-open');overlay?.classList.remove('intro-exiting');content.forEach(el=>{el.inert=false;});active=false;try{sessionStorage.setItem(key,'1');}catch{}if(restoreFocus){const target=previousFocus?.isConnected&&previousFocus!==document.body?previousFocus:document.getElementById('open-book');target?.focus({preventScroll:true});}}
function dismiss(){if(!active)return;clearTimeout(autoTimer);clearTimeout(failsafe);if(reduced){cleanup();return;}overlay.classList.add('intro-exiting');exitTimer=setTimeout(()=>cleanup(),460);}
function finishWhenReady(){if(!active||!ready)return;clearTimeout(autoTimer);autoTimer=setTimeout(dismiss,Math.max(0,(reduced?0:1250)-(performance.now()-started)));}
function show(replay=false){if(active){finishWhenReady();return;}clearTimers();active=true;previousFocus=document.activeElement;started=performance.now();root.classList.add('intro-pending','intro-open');overlay.classList.remove('intro-exiting');content.forEach(el=>{el.inert=true;});if(!reduced)skip.focus({preventScroll:true});autoTimer=setTimeout(dismiss,reduced?150:1850);failsafe=setTimeout(()=>cleanup(),2800);if(replay)ready=true;finishWhenReady();}
if(shouldShow){root.classList.add('intro-pending','intro-open');failsafe=setTimeout(()=>{root.classList.remove('intro-pending','intro-open');document.querySelectorAll('header,main,footer').forEach(el=>{el.inert=false;});},4000);}
function mount(){overlay=document.getElementById('brand-intro');skip=document.getElementById('intro-skip');content=[...document.querySelectorAll('header,main,footer')];skip.addEventListener('click',dismiss);document.getElementById('intro-replay')?.addEventListener('click',()=>show(true));document.addEventListener('keydown',e=>{if(!active)return;if(e.key==='Escape'){e.preventDefault();dismiss();}if(e.key==='Tab'){e.preventDefault();skip.focus();}});ready=document.readyState==='complete';window.addEventListener('load',()=>{ready=true;finishWhenReady();},{once:true});if(shouldShow)show();else root.classList.remove('intro-pending','intro-open');}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount,{once:true});else mount();
})();
